import * as React from 'react';
import { useDiagnosticWarnings, warnOnce } from '../utility/diagnostics';
import { getFlowFragmentState } from './flow-core';
import { StaticFlowContext } from './flow-context';
import { FlowTextSplitContext } from './flow-text';
import { useView } from './view';
import { normalizeItemGroup, getFirstFragmentPositions, getPlannedGroupHeadersByItemIndex, useMetaDefaultsCheck, cloneAsChild, resolveItemMeta, resolveItemClassName, renderFlowItem, breakAttributes, unplaceableFitStyle, shadowSplit, type FlowItemRendering } from './flow-render';
import { validateFlowColumnLayout } from './flow-core';
import type { FlowColumnsProps, DefaultFlowItemType, StaticFlowChunk, StaticFlowLayoutNode, StaticFlowLayoutFragment, StaticFlowColumnsRenderContext, StaticFlowColumnsContainerProps, StaticFlowUnplaceableItem, StaticFlowFragmentContext } from './flow-types';

export function FlowColumns<TItem, TType extends string = DefaultFlowItemType<TItem>>({
  id,
  items,
  layout,
  getKey,
  renderItem,
  getItemMeta,
  metaDefaults,
  getItemType: resolveItemType,
  getItemGroup,
  renderGroupHeader,
  className = '',
  itemClassName,
  groupHeaderClassName,
  renderUnplaceableItem,
  getColumnGroupProps,
  getColumnProps,
  getColumnItemProps,
  asChild = false,
  as = 'div',
}: FlowColumnsProps<TItem, TType>) {
  validateFlowColumnLayout({ nodes: layout, itemCount: items.length, flowId: id });
  const context = React.useContext(StaticFlowContext);
  const outerSplit = React.useContext(FlowTextSplitContext);
  const Root = as as React.ElementType;
  const continuationCopy = context?.copy === 'continuation';
  const chunks = context?.chunksByFlowId?.[id];
  const activeChunk = context?.mode === 'visible' && chunks
    ? chunks[context.pageIndex]
    : undefined;
  const isMeasurement = context?.mode !== 'visible';
  const pageIndex = context?.mode === 'visible' ? context.pageIndex : 0;
  const pageCount = context?.mode === 'visible' && chunks ? chunks.length : 1;
  const itemGroups = items.map((item, index) => normalizeItemGroup(getItemGroup?.(item, index)));
  const groupKeys = itemGroups.map((entry) => entry?.key);
  const columnsContext: StaticFlowColumnsRenderContext = {
    flowId: id,
  };

  useMetaDefaultsCheck('FlowColumns', id, items, metaDefaults, resolveItemType);

  // `growSheet` applies in the screen view only, to items outside a column group (as in Static.Flow);
  // an item in a column group keeps the print rules. Development builds say so once per item.
  const growSheets = useView() === 'screen';
  const diagnostics = useDiagnosticWarnings();
  const pageUnplaceable = activeChunk?.unplaceable;
  const ignoredGrowSheet = growSheets && pageUnplaceable && items[pageUnplaceable.index] !== undefined &&
    resolveItemMeta(items[pageUnplaceable.index], pageUnplaceable.index, resolveItemType, metaDefaults, getItemMeta).growSheet
    ? pageUnplaceable.key
    : undefined;
  React.useEffect(() => {
    if (!diagnostics || !ignoredGrowSheet) return;
    warnOnce(
      `flow-columns-grow-sheet:${id}:${ignoredGrowSheet}`,
      `[uhuu-components] Static.FlowColumns "${id}": item "${ignoredGrowSheet}" has growSheet, which an item ` +
      'in a column group does not take; it is scaled to fit, as in print. Place it outside the column group.'
    );
  }, [diagnostics, id, ignoredGrowSheet]);
  // A group with `growSheet` inside a column group flows as in print; say so once per group.
  const ignoredGrowGroup = React.useMemo(() => {
    if (!growSheets) return undefined;
    for (const node of layout) {
      if (node.kind !== 'columns') continue;
      for (const column of node.columns) {
        for (const index of column.indexes) {
          if (itemGroups[index]?.growSheet) return itemGroups[index]!.key;
        }
      }
    }
    return undefined;
  }, [growSheets, layout, itemGroups]);
  React.useEffect(() => {
    if (!diagnostics || !ignoredGrowGroup) return;
    warnOnce(
      `flow-columns-grow-group:${id}:${ignoredGrowGroup}`,
      `[uhuu-components] Static.FlowColumns "${id}": group "${ignoredGrowGroup}" has growSheet, which a group ` +
      'in a column group does not take; its items flow as in print. Place the group outside the column group.'
    );
  }, [diagnostics, id, ignoredGrowGroup]);
  const rendering: FlowItemRendering<TItem> = { flowId: id, asChild, renderItem, renderGroupHeader, groupHeaderClassName };

  const renderUnplaceable = (
    unplaceable: StaticFlowUnplaceableItem | undefined,
    printItem: () => React.ReactNode
  ): React.ReactNode => {
    if (!unplaceable) return null;
    // A custom renderer that returns nothing falls back to the default, as before.
    const custom = renderUnplaceableItem?.(unplaceable, { flowId: id, pageIndex, pageCount });
    if (custom == null) return printItem();
    const cloned = asChild && cloneAsChild(custom, {
      'data-uhuu-flow-unplaceable': 'true',
      'data-uhuu-flow-unplaceable-key': unplaceable.key,
      'data-uhuu-flow-column-id': unplaceable.columnId,
    }, { flowId: id, source: 'renderUnplaceableItem' });
    if (cloned) return cloned;
    return (
      <div
        style={{ display: 'contents' }}
        data-uhuu-flow-unplaceable="true"
        data-uhuu-flow-unplaceable-key={unplaceable.key}
        data-uhuu-flow-column-id={unplaceable.columnId}
      >
        {custom}
      </div>
    );
  };

  const renderIndexes = (
    rawIndexes: number[],
    plannedChunk?: StaticFlowChunk,
    resolveContainerProps?: (itemIndex: number) => StaticFlowColumnsContainerProps | undefined,
    markAsLayoutNode = false,
    sourceTrackIndexes?: number[]
  ): React.ReactNode[] => {
    const visibleIndexes = rawIndexes.filter((itemIndex) => (
      Number.isInteger(itemIndex) && itemIndex >= 0 && itemIndex < items.length
    ));
    const fragmentPositions = getFirstFragmentPositions(visibleIndexes);
    const sourceTrackPositions = sourceTrackIndexes
      ? getFirstFragmentPositions(sourceTrackIndexes)
      : undefined;
    const plannedGroupHeaders = renderGroupHeader
      ? getPlannedGroupHeadersByItemIndex(plannedChunk?.groupHeaders)
      : undefined;

    return visibleIndexes.map((itemIndex) => {
      const item = items[itemIndex];
      if (item === undefined) return null;
      const key = getKey(item, itemIndex);
      const group = itemGroups[itemIndex];
      const fragmentIndex = fragmentPositions.get(itemIndex) ?? -1;
      const sourceTrackPosition = sourceTrackPositions?.get(itemIndex) ?? -1;
      const coreFragment = getFlowFragmentState({
        itemIndex,
        fragmentIndexes: visibleIndexes,
        fragmentIndex,
        groupKeys,
        pageIndex,
        pageCount,
        itemCount: items.length,
        previousSourceIndex: plannedChunk?.previousSourceIndex ?? (
          sourceTrackPosition > 0 ? sourceTrackIndexes?.[sourceTrackPosition - 1] : undefined
        ),
      });
      const fragment: StaticFlowFragmentContext<TItem> = {
        ...coreFragment,
        flowId: id,
        itemKey: key,
        item,
      };
      const meta = resolveItemMeta(item, itemIndex, resolveItemType, metaDefaults, getItemMeta);
      const containerProps = resolveContainerProps?.(itemIndex);
      const plannedUnplaceable = plannedChunk?.unplaceable?.index === itemIndex ? plannedChunk.unplaceable : undefined;
      const { header, element } = renderFlowItem(rendering, {
        item,
        itemIndex,
        fragment,
        group,
        plannedGroupHeaders,
        // Joined: a wrapper without classes keeps its empty class attribute, as it always has.
        className: [resolveItemClassName(itemClassName, item, itemIndex), containerProps?.className].filter(Boolean).join(' '),
        attributes: {
          'data-uhuu-flow-item': 'true',
          'data-uhuu-flow-layout-node': markAsLayoutNode ? 'item' : undefined,
          'data-uhuu-flow-key': String(key),
          'data-uhuu-flow-index': itemIndex,
          'data-uhuu-flow-unplaceable': plannedUnplaceable ? 'true' : undefined,
          'data-uhuu-flow-unplaceable-key': plannedUnplaceable?.key,
          'data-uhuu-flow-column-id': plannedUnplaceable?.columnId,
          ...breakAttributes(meta, group),
          'data-uhuu-flow-grow-sheet': growSheets && meta.growSheet ? 'true' : undefined,
          'data-uhuu-flow-header-grow-sheet': growSheets && group?.growSheet ? 'true' : undefined,
        },
        baseStyle: containerProps?.style,
        forcedStyle: plannedUnplaceable ? unplaceableFitStyle(plannedUnplaceable) : undefined,
      });

      return (
        <React.Fragment key={key}>
          {outerSplit ? shadowSplit(header) : header}
          {outerSplit ? shadowSplit(element) : element}
        </React.Fragment>
      );
    });
  };

  const sourceColumnNodes = new Map(
    layout
      .filter((node): node is Extract<StaticFlowLayoutNode, { kind: 'columns' }> => (
        node.kind === 'columns'
      ))
      .map((node) => [node.id, node])
  );
  // A continuation measurement copy only lays the region out: its height is all that is read.
  const renderedLayout = continuationCopy
    ? []
    : isMeasurement
      ? layout
      : (activeChunk?.layout ?? []);

  return (
    <Root
      className={className}
      data-uhuu-flow="true"
      data-uhuu-flow-id={id}
      data-uhuu-flow-layout="columns"
      data-uhuu-flow-as-child={asChild ? 'true' : undefined}
      data-uhuu-flow-item-count={asChild && isMeasurement ? (continuationCopy ? 0 : items.length) : undefined}
    >
      {renderedLayout.map((entry, layoutIndex) => {
        if (entry.kind === 'item') {
          return (
            <React.Fragment key={`item:${entry.index}:${layoutIndex}`}>
              {renderIndexes([entry.index], undefined, undefined, true)}
            </React.Fragment>
          );
        }
        if (entry.kind === 'items') {
          return (
            <React.Fragment key={`items:${layoutIndex}`}>
              {renderUnplaceable(
                entry.chunk.unplaceable,
                () => renderIndexes([entry.chunk.unplaceable!.index], entry.chunk, undefined, true)
              )}
              {renderIndexes(entry.chunk.indexes, entry.chunk, undefined, true)}
            </React.Fragment>
          );
        }

        const sourceNode = isMeasurement
          ? (entry as Extract<StaticFlowLayoutNode, { kind: 'columns' }>)
          : sourceColumnNodes.get(entry.id);
        if (!sourceNode) return null;
        const sourceColumnsById = new Map(sourceNode.columns.map((column) => [column.id, column]));
        const renderedColumns: Array<{ id: string; chunk?: StaticFlowChunk }> = isMeasurement
          ? sourceNode.columns.map((column) => ({ id: column.id }))
          : (entry as Extract<StaticFlowLayoutFragment, { kind: 'columns' }>).columns;
        const groupProps = getColumnGroupProps?.(sourceNode, columnsContext);

        return (
          <div
            key={`columns:${sourceNode.id}:${layoutIndex}`}
            className={groupProps?.className}
            style={{
              display: 'flex',
              width: '100%',
              alignItems: 'flex-start',
              ...groupProps?.style,
            }}
            data-uhuu-flow-layout-node="columns"
            data-uhuu-flow-layout-id={sourceNode.id}
          >
            {renderedColumns.map((renderedColumn) => {
              const sourceColumn = sourceColumnsById.get(renderedColumn.id);
              if (!sourceColumn) return null;
              const columnProps = getColumnProps?.(sourceNode, sourceColumn, columnsContext);
              const columnIndexes = renderedColumn.chunk?.indexes ?? sourceColumn.indexes;

              return (
                <div
                  key={sourceColumn.id}
                  className={columnProps?.className}
                  style={{
                    minWidth: 0,
                    flex: '1 1 0%',
                    display: 'flex',
                    flexDirection: 'column',
                    ...columnProps?.style,
                  }}
                  data-uhuu-flow-column={sourceColumn.id}
                >
                  {renderUnplaceable(
                    renderedColumn.chunk?.unplaceable,
                    () => renderIndexes(
                      [renderedColumn.chunk!.unplaceable!.index],
                      renderedColumn.chunk,
                      (itemIndex) => getColumnItemProps?.(sourceNode, sourceColumn, itemIndex, columnsContext),
                      false,
                      sourceColumn.indexes
                    )
                  )}
                  {renderIndexes(
                    columnIndexes,
                    renderedColumn.chunk,
                    (itemIndex) => getColumnItemProps?.(
                      sourceNode,
                      sourceColumn,
                      itemIndex,
                      columnsContext
                    ),
                    false,
                    sourceColumn.indexes
                  )}
                </div>
              );
            })}
          </div>
        );
      })}
    </Root>
  );
}
