import PageSizeUtils from '../../utility/PageSizeUtils.js';
import {
  getCoverSpreadWarnings,
  planCoverSpread,
  resolveBinding,
} from '../../pagination-static/spread-core.js';

/**
 * Drop `binding` from a page format. Everything that renders ONE page (flow
 * measurement, thumbnails, add/reorder dialogs, non-cover filters) must use a
 * binding-less setup, otherwise Pagination would publish the wide cover sheet
 * as the `@page` size for plain pages.
 *
 * @template T
 * @param {T} pageFormat
 * @returns {T}
 */
export function omitBinding(pageFormat) {
  if (!pageFormat || typeof pageFormat !== 'object' || !('binding' in pageFormat)) return pageFormat;
  // eslint-disable-next-line no-unused-vars
  const { binding, ...rest } = pageFormat;
  return rest;
}

/**
 * Is a cover spread even a candidate? True when the page format declares a
 * perfect binding AND the active filter is `cover`. Needs no page list, so it
 * can be decided before flow measurement.
 *
 * @param {{ binding?: import('../../pagination-static/spread-core.js').BindingConfig | null } | undefined} pageFormat
 * @param {{ mode?: string } | undefined} pageFilter
 */
export function isCoverSpreadCandidate(pageFormat, pageFilter) {
  return !!resolveBinding(pageFormat?.binding) && pageFilter?.mode === 'cover';
}

/**
 * Decide how PageEditor renders the current filter result.
 *
 * - not a candidate → `{ active: false }`, plain pages, binding stripped from the setup
 * - candidate but unplannable (e.g. coverPageCount 3) → `{ active: false }` plus
 *   developer warnings, plain pages
 * - candidate and plannable → `{ active: true, plan, setup }` where `setup`
 *   carries the binding (so `@page` becomes the cover sheet) and forces the
 *   single-page preview (a spread is already two pages side by side)
 *
 * @template TPage
 * @param {{
 *   pageFormat?: Record<string, any>,
 *   pageFilter?: { mode?: string, coverPageCount?: number },
 *   pages?: TPage[],
 * }} input
 */
export function resolveCoverSpreadLayout({ pageFormat = {}, pageFilter, pages = [] } = {}) {
  const plain = { active: false, plan: null, setup: omitBinding(pageFormat), warnings: [] };
  if (!isCoverSpreadCandidate(pageFormat, pageFilter)) return plain;

  const binding = resolveBinding(pageFormat.binding);
  const dimensions = PageSizeUtils.resolveDimensions(pageFormat);
  const geometry = { ...dimensions, bleed: PageSizeUtils.clampBleed(pageFormat.bleed), binding };

  const plan = planCoverSpread({ ...geometry, coverPages: pages });
  const warnings = getCoverSpreadWarnings({
    ...geometry,
    coverPageCount: pageFilter.coverPageCount ?? 2,
    coverPages: pages,
    flowCoverPages: pages.filter((page) => page && page.hasFlow).length,
  });

  if (!plan) return { ...plain, warnings };

  return {
    active: true,
    plan,
    setup: { ...pageFormat, binding, preview: 'single_page' },
    warnings,
  };
}
