import * as React from 'react';
import { useDiagnosticWarnings } from '../utility/diagnostics';
import { getEffectiveScale } from './flow-measure';
import { inspectFlowTextContent, sliceFlowTextContent } from './flow-text-slice';
import { useIsoLayoutEffect } from '../utility/use-iso-layout-effect';
import { warnOnce } from '../utility/warn-once.js';

/** The piece of a split item a visible sheet renders (`StaticFlowChunk.splits`). */
export type StaticFlowTextSplit = {
  /** 0-based piece number. */
  part: number;
  parts: number;
  /** The piece's text: UTF-16 offsets `[from, to)` across the FlowText's text. */
  from: number;
  to: number;
  /** Justified text: a piece that ends mid-paragraph justifies its last line too. */
  justify?: boolean;
  /** The planned height of the piece's lines, in layout px. */
  textHeight?: number;
  /** Text offsets where the piece's measured lines broke with a hyphen (its own end included). */
  hyphens?: number[];
};

/**
 * The piece of its item a FlowText renders. Flow provides it around each split item, and shadows it
 * with `null` around the items of a Flow nested in one.
 */
export const FlowTextSplitContext = React.createContext<StaticFlowTextSplit | null>(null);

export type FlowTextProps = React.HTMLAttributes<HTMLElement> & {
  /** A string (may contain `\n`) or inline content: text, span/strong/em/b/i/a/small/sub/sup/br. */
  children?: React.ReactNode;
  /** Default `div`. A block, so its line boxes are its own. */
  as?: keyof HTMLElementTagNameMap;
  className?: string;
  style?: React.CSSProperties;
};


/** The element's content height in layout px, and its line height. */
function contentBox(element: HTMLElement) {
  const rect = element.getBoundingClientRect();
  if (!(rect.height > 0)) return undefined;
  const style = window.getComputedStyle(element);
  const value = (property: string) => Number.parseFloat(style.getPropertyValue(property) || '0') || 0;
  return {
    height: rect.height / getEffectiveScale(element) -
      value('padding-top') - value('padding-bottom') - value('border-top-width') - value('border-bottom-width'),
    lineHeight: value('line-height') || value('font-size') * 1.2 || 16,
  };
}

/**
 * Text a Static.Flow item may split between lines. The item is split only when it does not fit the
 * room left on its sheet; each piece renders the item again, with this FlowText showing the lines
 * of that piece. The hidden measurement copy renders the whole text, and outside a split it renders
 * its children unchanged.
 */
export function FlowText({ children, as = 'div', className, style, ...attributes }: FlowTextProps) {
  const split = React.useContext(FlowTextSplitContext);
  const diagnostics = useDiagnosticWarnings();
  const ref = React.useRef<HTMLElement>(null);
  const content = React.useMemo(() => inspectFlowTextContent(children), [children]);
  const { text, problem } = content;
  const piece = split && !problem ? sliceFlowTextContent(children, content, split) : null;
  const textHeight = piece ? split?.textHeight : undefined;

  React.useEffect(() => {
    if (!problem || !diagnostics) return;
    warnOnce(
      `flow-text-content:${problem.reason}:${problem.name}`,
      `[uhuu-components] Static.FlowText holds ${problem.reason === 'block-content' ? `a <${problem.name}>` : `<${problem.name}>`}: ` +
      'only text and inline text elements (span, strong, em, b, i, a, small, sub, sup, br) can split between ' +
      'lines, so its item is not split. Put block content in the item outside the FlowText, and an Editable ' +
      'around the FlowText rather than inside it.'
    );
  }, [problem, diagnostics]);

  // A slice that lays out taller than its planned lines re-wrapped: the piece overfills its sheet.
  // A re-wrap adds at least a line; measured through the editor's zoom, against line boxes placed
  // between glyph rows, a piece that did not re-wrap can still differ from its plan by a pixel or two.
  useIsoLayoutEffect(() => {
    const element = ref.current;
    if (textHeight === undefined || !element || !diagnostics) return;
    const box = contentBox(element);
    if (!box || box.height <= textHeight + Math.max(2, box.lineHeight / 2)) return;
    const height = box.height;
    warnOnce(
      `flow-text-rewrap:${text.slice(0, 40)}`,
      `[uhuu-components] Static.FlowText "${text.slice(0, 40)}…": a piece lays out ${Math.round(height - textHeight)}px ` +
      'taller than the lines it was planned with, so it re-wrapped. A continuation must give the FlowText the ' +
      'width it measured with (keep a label cell, empty), and ::first-line styles or text-wrap: balance | pretty ' +
      're-flow a slice.'
    );
  });

  const Tag = as as React.ElementType;
  const pieceStyle = piece && split
    ? {
      ...style,
      ...(split.part > 0 ? { textIndent: 0 } : {}),
      ...(split.justify && piece.justifyLast ? { textAlignLast: 'justify' as const } : {}),
      // The measured hyphenation, pinned: a truncated word would hyphenate elsewhere.
      ...(piece.manualHyphens ? { hyphens: 'manual' as const, WebkitHyphens: 'manual' as const } : {}),
    }
    : style;
  const props = {
    ...attributes,
    ref,
    className,
    style: pieceStyle,
    'data-uhuu-flow-text': 'true',
    'data-uhuu-flow-text-unsplittable': problem?.reason,
  };
  return piece ? React.createElement(Tag, props, ...piece.children) : React.createElement(Tag, props, children);
}
