// One report per mistake for the page's lifetime. Diagnostics fire from renders, observers and
// re-measures; without this a single mistake logs on every pass. `key` names what is wrong and
// where, so two different mistakes both report. No React or DOM: Node tests import it directly.
const reported = new Set();

/** `console.warn` once per `key`. */
export function warnOnce(key, ...message) {
  if (reported.has(key)) return;
  reported.add(key);
  console.warn(...message);
}

/** `console.error` once per `key`, for template input that fails. */
export function errorOnce(key, ...message) {
  if (reported.has(key)) return;
  reported.add(key);
  console.error(...message);
}

/** An image that failed to load prints empty: say which, once per URL, in every environment. */
export function warnImageFailed(src) {
  if (!src) return;
  warnOnce(
    `image:${src}`,
    `[uhuu-components] Image ${src} failed to load, so it prints empty. Check the URL, or pass onError ` +
    'to render a fallback.'
  );
}
