/**
 * Tells the host which uhuu-components a template runs, so the document editor's developer tools
 * can show it (Info panel, copied debug info). One message per page load, sent through the SDK's
 * existing `$uhuu.editor.post` (the channel `patchPayload` uses), so no SDK change is needed:
 *
 *   { action: 'templateRuntime', runtime: { 'uhuu-components': '0.4.2' } }
 *
 * `<html data-uhuu-components="0.4.2">` carries the same for renderers and anyone inspecting the
 * page. Nothing is sent in renderer mode or without a host; an editor that does not know the
 * action drops it.
 */

/* global __UHUU_COMPONENTS_VERSION__ */
/** The package version, set at build time (`vite.config.js`); `dev` when running from source. */
export const UHUU_COMPONENTS_VERSION =
  typeof __UHUU_COMPONENTS_VERSION__ === 'string' ? __UHUU_COMPONENTS_VERSION__ : 'dev';

export const RUNTIME_ATTRIBUTE = 'data-uhuu-components';
export const RUNTIME_ACTION = 'templateRuntime';

const ANNOUNCED = '__uhuuComponentsAnnounced';

const post = (win) => {
  const editor = win.$uhuu?.editor;
  if (typeof editor?.post !== 'function') return false;
  editor.post({ action: RUNTIME_ACTION, runtime: { 'uhuu-components': UHUU_COMPONENTS_VERSION } });
  return true;
};

/**
 * Announces this runtime once per window. Called when the first document root mounts. When the
 * SDK has not loaded yet, it tries again once the page has loaded.
 */
export function announceTemplateRuntime(win = typeof window === 'undefined' ? undefined : window) {
  if (!win || win[ANNOUNCED]) return;
  win[ANNOUNCED] = true;
  try { win.document?.documentElement?.setAttribute(RUNTIME_ATTRIBUTE, UHUU_COMPONENTS_VERSION); } catch { /* read-only document */ }
  if (win.$uhuu_renderer || !win.parent || win.parent === win) return;
  try {
    if (post(win)) return;
    if (win.document?.readyState !== 'complete') {
      win.addEventListener?.('load', () => { try { post(win); } catch { /* host gone */ } }, { once: true });
    }
  } catch { /* a host that refuses the message changes nothing on the page */ }
}
